package com.prima.factory.device.collector; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component public class SimulatorScheduler {private final JdbcTemplate db;private final EquipmentDataCollector collector;private final boolean enabled;public SimulatorScheduler(JdbcTemplate db,EquipmentDataCollector c,@Value("${simulator.enabled:true}")boolean e){this.db=db;collector=c;enabled=e;}@Scheduled(fixedDelayString="${simulator.interval-ms:1000}") void tick(){if(!enabled)return;List<Long> ids=db.queryForList("SELECT id FROM equipment WHERE is_active=1",Long.class);ids.parallelStream().forEach(id->{try{collector.collect(id);}catch(Exception ex){db.update("UPDATE collection_health SET consecutive_failures=consecutive_failures+1,data_quality='BAD',updated_at=CURRENT_TIMESTAMP(3) WHERE equipment_id=?",id);}});db.update("INSERT INTO service_heartbeat(service_name,status,last_heartbeat_at,details) VALUES('DEVICE_SERVER','UP',CURRENT_TIMESTAMP(3),'simulator') ON DUPLICATE KEY UPDATE status='UP',last_heartbeat_at=CURRENT_TIMESTAMP(3)");}}
